const apiDefault = 'http://10.0.2.2:3000/api';

void main() => runApp(const AlmoxApp());

class AlmoxApp extends StatelessWidget {
  const AlmoxApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(debugShowCheckedModeBanner:false,title:'A Liga Almoxarifado',theme:ThemeData(useMaterial3:true,colorSchemeSeed:Colors.blueGrey),home:const LoginPage());
}

class Api {
  static Future<String> base() async { final p=await SharedPreferences.getInstance(); return p.getString('api')??apiDefault; }
  static Future<dynamic> call(String method,String path,[Map<String,dynamic>? data]) async {
    final u=Uri.parse('${await base()}$path'); final h={'Content-Type':'application/json'}; http.Response r;
    if(method=='GET') r=await http.get(u); else if(method=='POST') r=await http.post(u,headers:h,body:jsonEncode(data??{})); else r=await http.patch(u,headers:h,body:jsonEncode(data??{}));
    if(r.statusCode>=400) throw Exception(r.body); return r.body.isEmpty?{}:jsonDecode(r.body);
  }
  static Future<List<dynamic>> list(String path) async => (await call('GET',path)) as List<dynamic>;
}

class LoginPage extends StatefulWidget { const LoginPage({super.key}); @override State<LoginPage> createState()=>_LoginPageState(); }
class _LoginPageState extends State<LoginPage>{
  final u=TextEditingController(text:'supervisor'),s=TextEditingController(text:'1234'),api=TextEditingController(text:apiDefault); bool busy=false; String? erro;
  Future<void> entrar() async { setState(()=>busy=true); try { final p=await SharedPreferences.getInstance(); await p.setString('api',api.text.trim().replaceAll(RegExp(r'\/$'),'')); final user=Map<String,dynamic>.from(await Api.call('POST','/login',{'usuario':u.text.trim(),'senha':s.text})); if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>HomePage(user:user))); } catch(e){if(mounted)setState(()=>erro=e.toString().replaceFirst('Exception: ',''));} finally{if(mounted)setState(()=>busy=false);} }
  @override Widget build(BuildContext c)=>Scaffold(body:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:460),child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.inventory_2,size:70),const Text('A Liga Almoxarifado',style:TextStyle(fontSize:28,fontWeight:FontWeight.bold)),const SizedBox(height:20),TextField(controller:u,decoration:const InputDecoration(labelText:'Usuário',border:OutlineInputBorder())),const SizedBox(height:10),TextField(controller:s,obscureText:true,decoration:const InputDecoration(labelText:'Senha',border:OutlineInputBorder())),const SizedBox(height:10),TextField(controller:api,decoration:const InputDecoration(labelText:'Servidor/API',border:OutlineInputBorder())),if(erro!=null)Padding(padding:const EdgeInsets.all(8),child:Text(erro!,style:const TextStyle(color:Colors.red))),SizedBox(width:double.infinity,height:50,child:FilledButton(onPressed:busy?null:entrar,child:Text(busy?'Entrando...':'ENTRAR')))]))));
}

