class RequesterPage extends StatefulWidget{final Map<String,dynamic> user;final VoidCallback reload;const RequesterPage({super.key,required this.user,required this.reload});@override State<RequesterPage> createState()=>_RequesterPageState();}
class _RequesterPageState extends State<RequesterPage>{final key=GlobalKey<FormState>();final empresa=TextEditingController(),func=TextEditingController(),produto=TextEditingController(),qtd=TextEditingController(text:'1'),tam=TextEditingController(),calc=TextEditingController(),obs=TextEditingController();String tipo='Uniforme';
