 Future<void> enviar()async{if(!key.currentState!.validate())return;try{final r=await Api.call('POST','/requisicoes',{'empresa':empresa.text.trim(),'funcionario':func.text.trim(),'tipo':tipo,'produto':produto.text.trim(),'quantidade':int.tryParse(qtd.text)??1,'tamanho':tam.text.trim(),'calcado':calc.text.trim(),'observacoes':obs.text.trim(),'solicitante':widget.user['nome'],'usuario':widget.user['usuario']});if(mounted)await showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Requisição enviada'),content:Text('Nº ${r['numero']}\nAguarde a disponibilidade para retirada.'),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('OK'))]));widget.reload();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}}
 Widget field(TextEditingController x,String label,{bool req=false})=>Padding(padding:const EdgeInsets.only(bottom:10),child:TextFormField(controller:x,decoration:InputDecoration(labelText:label,border:const OutlineInputBorder()),validator:req?(v)=>v==null||v.trim().isEmpty?'Informe este campo':null:null));
 @override Widget build(BuildContext c)=>SingleChildScrollView(padding:const EdgeInsets.all(16),child:Form(key:key,child:Column(children:[const Align(alignment:Alignment.centerLeft,child:Text('NOVA REQUISIÇÃO',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold))),const SizedBox(height:14),field(empresa,'Empresa / Condomínio',req:true),field(func,'Funcionário',req:true),DropdownButtonFormField<String>(initialValue:tipo,decoration:const InputDecoration(labelText:'Tipo de solicitação',border:OutlineInputBorder()),items:['Uniforme','EPI','Material de Limpeza','Material'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(x){setState(()=>tipo=x!);produto.clear();}),const SizedBox(height:10),if(produtos.length>1)DropdownButtonFormField<String>(decoration:const InputDecoration(labelText:'Produto solicitado',border:OutlineInputBorder()),items:produtos.map((x)=>DropdownMenuItem(value:x,child:Text(x,overflow:TextOverflow.ellipsis))).toList(),onChanged:(x)=>produto.text=x??'',validator:(x)=>x==null||x.isEmpty?'Selecione o produto':null)else field(produto,'Produto solicitado',req:true),field(qtd,'Quantidade',req:true),field(tam,'Tamanho do uniforme'),field(calc,'Numeração do calçado'),field(obs,'Observações'),Align(alignment:Alignment.centerLeft,child:Text('Supervisor/Inspetora: ${widget.user['nome']}')),const SizedBox(height:10),SizedBox(width:double.infinity,height:50,child:FilledButton.icon(onPressed:enviar,icon:const Icon(Icons.send),label:const Text('ENVIAR REQUISIÇÃO')))])));
}

