 @override Widget build(BuildContext c){final list=widget.rs.where((r)=>filtro=='Todos'||r['status']==filtro).toList();return Column(children:[SingleChildScrollView(scrollDirection:Axis.horizontal,padding:const EdgeInsets.all(8),child:Row(children:['Todos','Pendente','Separando','Disponível para Entrega','Entregue'].map((x)=>Padding(padding:const EdgeInsets.only(right:6),child:ChoiceChip(label:Text(x),selected:filtro==x,onSelected:(_)=>setState(()=>filtro=x))).toList())),Expanded(child:RefreshIndicator(onRefresh:()async=>widget.reload(),child:ListView(padding:const EdgeInsets.all(10),children:[Text('REQUISIÇÕES RECEBIDAS: ${list.length}',style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),...list.map((r)=>Card(child:ListTile(leading:Icon(r['status']=='Entregue'?Icons.check_circle:Icons.inventory_2),title:Text('${r['numero']} • ${r['empresa']}'),subtitle:Text('${r['funcionario']} • ${r['tipo']} • ${r['produto']} x${r['quantidade']}\n${r['status']}'),onTap:()=>showModalBottomSheet(context:c,builder:(_)=>Padding(padding:const EdgeInsets.all(20),child:Wrap(children:[Text('REQUISIÇÃO ${r['numero']}',style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:12),Text('Empresa: ${r['empresa']}\nFuncionário: ${r['funcionario']}\nResponsável: ${r['solicitante']}\nProduto: ${r['produto']}\nTamanho: ${r['tamanho']??''}\nQuantidade: ${r['quantidade']}'),const SizedBox(height:12),if(r['status']=='Pendente')FilledButton.icon(onPressed:(){Navigator.pop(c);status(r['id'].toString(),'Separando');},icon:const Icon(Icons.inventory),label:const Text('SEPARADO / INICIAR SEPARAÇÃO')),if(r['status']=='Separando')FilledButton.icon(onPressed:(){Navigator.pop(c);status(r['id'].toString(),'Disponível para Entrega');},icon:const Icon(Icons.check_box),label:const Text('DISPONÍVEL PARA ENTREGA'))]))))])))]));}
}

