class SignaturePage extends StatefulWidget{final Map<String,dynamic> r;const SignaturePage({super.key,required this.r});@override State<SignaturePage> createState()=>_SignaturePageState();}
class _SignaturePageState extends State<SignaturePage>{List<Offset?> pts=[];bool busy=false;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Comprovante de Entrega')),body:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Funcionário: ${widget.r['funcionario']}'),Text('Empresa: ${widget.r['empresa']}'),Text('Produto: ${widget.r['produto']} | Qtd: ${widget.r['quantidade']}'),Text('Tamanho: ${widget.r['tamanho']??''}'),const SizedBox(height:15),const Text('Assinatura do recebimento:',style:TextStyle(fontWeight:FontWeight.bold)),const SizedBox(height:8),Expanded(child:Container(decoration:BoxDecoration(border:Border.all(),borderRadius:BorderRadius.circular(8)),child:GestureDetector(onPanStart:(d)=>setState(()=>pts.add(d.localPosition)),onPanUpdate:(d)=>setState(()=>pts.add(d.localPosition)),onPanEnd:(_)=>setState(()=>pts.add(null)),child:CustomPaint(painter:SigPainter(pts),child:const SizedBox.expand())))),Row(children:[TextButton(onPressed:()=>setState(()=>pts=[]),child:const Text('LIMPAR')),const Spacer(),FilledButton(onPressed:busy||pts.whereType<Offset>().isEmpty?null:confirmar,child:Text(busy?'Salvando...':'CONFIRMAR RECEBIMENTO'))])])));
 Future<void> confirmar()async{setState(()=>busy=true);try{await Api.call('PATCH','/requisicoes/${widget.r['id']}/entrega',{'recebidoPor':widget.r['funcionario'],'assinatura':jsonEncode(pts.map((p)=>p==null?null:[p.dx,p.dy]).toList())});if(mounted)Navigator.pop(c,true);}catch(e){if(mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text(e.toString())));}finally{if(mounted)setState(()=>busy=false);}}
}
class SigPainter extends CustomPainter{final List<Offset?> pts;SigPainter(this.pts);@override void paint(Canvas c,Size s){final p=Paint()..strokeWidth=2.5..strokeCap=StrokeCap.round;for(int i=1;i<pts.length;i++){if(pts[i-1]!=null&&pts[i]!=null)c.drawLine(pts[i-1]!,pts[i]!,p);}}@override bool shouldRepaint(covariant SigPainter old)=>old.pts!=pts;}
